core_observability_vectors.machine_source:
format: 1
namespace: example.transaction_server

events:
  action_sink:
    direction: internal
    payload:
      amount: { type: int, required: true }
  new_request:
    direction: input
    payload:
      transaction_id: { type: string, required: true }
  received: { direction: input }
  authorized: { direction: input }
  priority_request: { direction: input }
  retry: { direction: input }
  retired_event: { direction: input }

machines:
  - machine_id: transaction_server
    root:
      type: composite
      deferred_event_capacity: 16
      initial: { transition_to: idle }
      states:
        idle:
          on_events:
            new_request: { transition_to: busy.receiving }
        busy:
          type: composite
          deferred_events: [new_request, retired_event]
          initial: { transition_to: busy.receiving }
          on_events:
            priority_request: { transition_to: idle }
          states:
            receiving:
              on_events:
                received:
                  action:
                    - send:
                        event: action_sink
                        to: { self: true }
                        payload: { amount: "1 % 0" }
                  transition_to: busy.authorizing
            authorizing:
              deferred_events: [priority_request, retry]
              on_events:
                new_request: {}
                retry: { guard: "false" }
                authorized: { transition_to: idle }
